contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(!c.initialized());
        } else {
            assert(
                c.initialized() &&
                c.feeRate() == _feeRate &&
                c.baseToken() == _baseToken &&
                c.nft() == _nft &&
                c.virtualBaseTokenReserves() == _virtualBaseTokenReserves &&
                c.virtualNftReserves() == _virtualNftReserves &&
                c.changeFee() == _changeFee &&
                c.merkleRoot() == _merkleRoot &&
                c.useStolenNftOracle() == _useStolenNftOracle &&
                c.payRoyalties() == _payRoyalties
            );
        }
    }
}

