contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 vb, uint128 vn, uint16 fr, uint256 w) public {
        require(fr <= 5_000);
        require(vn > 1);
        require(w > 0 && w < vn);

        c.initialize(
            address(0),
            address(0x0000000000000000000000000000000000000001),
            vb,
            vn,
            0,
            fr,
            bytes32(0),
            false,
            false
        );

        (uint256 net, uint256 fee, uint256 proto) = c.buyQuote(w);

        uint256 inputAmount = net - fee - proto;

        assert(net >= fee + proto && fee == inputAmount * fr / 10_000);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _vb,
        uint128 _vn,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
