contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _vb,
        uint128 _vn,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256 _inputAmount
    ) public {
        require(_feeRate <= 5_000 && _vn > 0);

        c.initialize(
            _baseToken, _nft, _vb, _vn, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties
        );

        uint128 vbBefore = c.virtualBaseTokenReserves();
        uint128 vnBefore = c.virtualNftReserves();
        uint16 fr = c.feeRate();

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(_inputAmount);

        uint256 outputAmount = _inputAmount * vbBefore / vnBefore;
        uint256 expectedFee = outputAmount * fr / 10_000;

        // sellQuote is a pure quote: it must not change state
        assert(
            c.virtualBaseTokenReserves() == vbBefore &&
            c.virtualNftReserves() == vnBefore &&
            feeAmount == expectedFee &&
            protocolFeeAmount <= outputAmount &&
            netOutputAmount == outputAmount - feeAmount - protocolFeeAmount
        );
    }

    receive() external payable {}
}

